cat > /app/hierarchical_model.stan <<'EOF'
data {
  int<lower=1> N;
  array[N] int<lower=0> y;
  array[N] int<lower=0> n;
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // Prior proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);

  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF

cat > /app/analysis.R <<'EOF'
options(mc.cores = parallel::detectCores())
Sys.setenv(LOCAL_CPP化 = "")

if (!requireNamespace("rstan", quietly = TRUE) ||
    as.character(utils::packageVersion("rstan")) != "2.32.7") {
  install.packages("rstan", version = "2.32.7", repos = "https://cloud.r-project.org", dependencies = TRUE)
}

library(rstan)
rstan_options(auto_write = TRUE)
options(mc.cores = parallel::detectCores())

input_file <- "/app/data.csv"
data_df <- read.csv(input_file, header = TRUE)
stopifnot(all(c("y", "n") %in% names(data_df)))
stan_data <- list(
  N = nrow(data_df),
  y = as.integer(data_df$y),
  n = as.integer(data_df$n)
)

model <- stan_model(file = "/app/hierarchical_model.stan")
fit <- sampling(
  model,
  data = stan_data,
  chains = 4,
  iter = 100000,
  seed = 1,
  refresh = 1000
)

posterior <- rstan::extract(fit, pars = c("alpha", "beta"), permuted = TRUE)
alpha_mean <- mean(posterior$alpha)
beta_mean <- mean(posterior$beta)

writeLines(sprintf("%.17g", alpha_mean), "/app/posterior_alpha_mean.txt")
writeLines(sprintf("%.17g", beta_mean), "/app/posterior_beta_mean.txt")
EOF

# Remove an accidental nonstandard environment assignment if present.
sed -i '/LOCAL_CPP/d' /app/analysis.R
ls -l /app/hierarchical_model.stan /app/analysis.R
